DECLARE r jsonb := '{"industry_code": "IND_WAT_001", "industry_name": "Water & Environmental Services", "domain_code": "WAT_D03", "domain_name": "Environmental Research & River Protection", "family_code": "WAT_RF03", "family_name": "Environmental Scientist", "role_code": "RMR-ROLE-03", "role_name": "River Protection Expert", "description": "Studies river conditions and helps people understand how environmental changes affect waterways. Future role: Environmental Scientist; the school course supports exploration, not scientific licensure.", "observable_behaviours": "Compare the Two Field Reports: align source ID, conditions, observations and missing fields side by side; identify which differences can be compared fairly; Build a Matched Runoff Comparison: compare the trays, keep the input and slope conditions matched, collect runoff separately and log source-specific readings; Write a Fair Field-Study Proposal: specify the research question, matched variables, measurements and evidence needed; state where conclusions remain limited; Prepare the Water-Authority Handover: summarise verified observations, missing measurements, limits and the responsible next testing or referral action", "role_work_context": "An environmental field team compares conditions near a river and considers land cover, runoff and missing site evidence before recommending further work. Students use model field records.", "typical_work_activities": "Align two field reports by site, conditions and source ID; Compare bare-soil and leaf-covered runoff using matched conditions; Draft a fair field study including the missing slope and rainfall controls; Explain findings and uncertainty in a responsible handover", "role_output_evidence": "Paired field-report comparison; Matched runoff experiment plan; Fair field-study proposal; Water-authority evidence summary; Learning modules: RMR-CAP-L03-M01 - Compare the Two Field Reports (Core, step 1), RMR-CAP-L03-M02 - Build a Matched Runoff Comparison (Important,