DECLARE r jsonb := '{"industry_code": "IND_WAT_001", "industry_name": "Water & Environmental Services", "domain_code": "WAT_D04", "domain_name": "Hydrology & Watershed Science", "family_code": "WAT_RF04", "family_name": "Hydrologist", "role_code": "RMR-ROLE-04", "role_name": "Rain & Flood Expert", "description": "Studies rain, river runoff and land cover to explain water movement and possible flood-related risks. Future role: Hydrologist; these school models do not predict real floods.", "observable_behaviours": "Compare the Two Field Reports: align source ID, conditions, observations and missing fields side by side; identify which differences can be compared fairly; Build a Matched Runoff Comparison: compare the trays, keep the input and slope conditions matched, collect runoff separately and log source-specific readings; Calculate Runoff Across Three Trials: calculate means 160 mL and 100 mL; compute 64% and 40% runoff; report the 24-percentage-point gap", "role_work_context": "A watershed or hydrology team needs fair rainfall-runoff comparisons and repeated data before giving advice about river flow, erosion and possible flood impacts.", "typical_work_activities": "Compare two field reports and identify non-matched conditions; Set up a matched bare-soil versus leaf-cover runoff comparison; Average three model runoff trials for each condition; Compute runoff percentages and state the percentage-point difference without overclaiming soil loss", "role_output_evidence": "Field-report comparison; Matched-tray method and reading log; Three-trial average calculation; Runoff percentage and limitation report; Learning modules: RMR-CAP-L03-M01 - Compare the Two Field Reports (Core, step 1), RMR-CAP-L03-M02 - Build a Matched Runoff Comparison (Important, step 2), RMR-CAP-L03-M03 - Calculate Runoff Across Three Trials (Important, step 3)", "primary_riasec": "I", "secondary_riasec": "R", "tertiary_riasec": "C", "riasec_reason": "Investigative work interprets rainfall and runo