DECLARE r jsonb := '{"industry_code": "IND_WAT_001", "industry_name": "Water & Environmental Services", "domain_code": "WAT_D06", "domain_name": "Water Quality & Public Safety", "family_code": "WAT_RF06", "family_name": "Water Quality Compliance Officer", "role_code": "RMR-ROLE-06", "role_name": "Water Safety Officer", "description": "Reviews test evidence and checks what remains unknown before an authorised water-safety decision. Future role: Water Quality Compliance Officer; students must not approve drinking-water safety.", "observable_behaviours": "Investigate the Cup B Conflict: retain T1 and T2; record a clean-tool fresh-strip T3 separately; compare all three and flag the unexplained T2 conditions; Evaluate the Filter Advertisement: quote the claim, compare it with supported filtration results, identify missing controls and write a bounded decision; Review an Unverified Acid-Base Protocol: list the described steps, identify the missing starting and final evidence and classify the outcome as unverified; Interpret the Fictional R-26 Report: keep pH beside each sample ID; classify A near-neutral, B acidic and C basic; identify untested safety indicators", "role_work_context": "A water-quality assurance team reviews sample evidence, conflicting results and test-method limitations before advising an authorised official. Approval is outside the student role.", "typical_work_activities": "Keep both Cup B observations and identify why a controlled retest is needed; Check whether a filter advertisement is supported by the tests; Mark the acid-base procedure as unverified when before/after evidence is absent; Review R-26 pH reports and missing microbial and chemical tests", "role_output_evidence": "Retest and discrepancy register; Claim-validation decision note; Unverified-protocol findings list; R-26 safety-evidence gap report; Learning modules: RMR-CAP-L02-M02 - Investigate the Cup B Conflict (Core, step 1), RMR-CAP-L04-M04 - Evaluate the Filter Advertisement (Important, step 2), RMR-CAP-L05-M03 - Review an Unverified Acid-Base Protocol (Important, step 3), RMR-CAP-L05-M04 - Interpret the Fictional R-26 Report (Supporting, step 4)", "primary_riasec": "C", "secondary_riasec": "I", "tertiary_riasec": "S", "riasec_reason": "Conventional work ensures records and methods meet review rules; Investigative work identifies unsupported claims; Social responsibility keeps public-facing recommendations careful.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Chemistry; B.Sc. Environmental Science; B.Tech. Environmental Engineering; M.Sc. Environmental Science", "apt_verbal_reasoning": 85, "apt_logical_reasoning": 89, "apt_numerical_reasoning": 79, "apt_data_interpretation": 92, "apt_pattern_recognition": 76, "apt_spatial_reasoning": 61, "big5_openness": 4, "big5_conscientiousness": 5, "big5_extraversion": 3, "big5_agreeableness": 4, "big5_emotional_stability": 5, "value_impact": 5, "value_status": 3, "value_autonomy": 3, "value_security": 5, "value_financial": 3, "value_lifestyle": 3, "value_creativity": 2, "value_leadership": 4, "aptitude_areas": "Data Interpretation|Logical Reasoning|Verbal Reasoning", "aptitude_rationale": "Water Safety Officer uses data interpretation, logical reasoning, verbal reasoning to keep both cup b observations and identify why a controlled retest is needed, check whether a filter advertisement is supported by the tests, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude.", "big_five_traits": "Conscientiousness|Emotional Stability|Agreeableness", "big_five_rationale": "Water Safety Officer benefits from conscientiousness, emotional stability, agreeableness when performing check whether a filter advertisement is supported by the tests and following through on r-26 safety-evidence gap report. Traits guide supportive coaching, not exclusion.", "work_values_list": "Impact|Security|Leadership", "work_values_rationale": "This pathway may reward impact, security, leadership through the work of keep both cup b observations and identify why a controlled retest is needed and producing a clear retest and discrepancy register. These are possible work priorities, not salary or job guarantees.", "profile": {"description": "Reviews test evidence and checks what remains unknown before an authorised water-safety decision. Future role: Water Quality Compliance Officer; students must not approve drinking-water safety.", "observable_behaviours": "Investigate the Cup B Conflict: retain T1 and T2; record a clean-tool fresh-strip T3 separately; compare all three and flag the unexplained T2 conditions; Evaluate the Filter Advertisement: quote the claim, compare it with supported filtration results, identify missing controls and write a bounded decision; Review an Unverified Acid-Base Protocol: list the described steps, identify the missing starting and final evidence and classify the outcome as unverified; Interpret the Fictional R-26 Report: keep pH beside each sample ID; classify A near-neutral, B acidic and C basic; identify untested safety indicators", "role_work_context": "A water-quality assurance team reviews sample evidence, conflicting results and test-method limitations before advising an authorised official. Approval is outside the student role.", "typical_work_activities": "Keep both Cup B observations and identify why a controlled retest is needed; Check whether a filter advertisement is supported by the tests; Mark the acid-base procedure as unverified when before/after evidence is absent; Review R-26 pH reports and missing microbial and chemical tests", "role_output_evidence": "Retest and discrepancy register; Claim-validation decision note; Unverified-protocol findings list; R-26 safety-evidence gap report; Learning modules: RMR-CAP-L02-M02 - Investigate the Cup B Conflict (Core, step 1), RMR-CAP-L04-M04 - Evaluate the Filter Advertisement (Important, step 2), RMR-CAP-L05-M03 - Review an Unverified Acid-Base Protocol (Important, step 3), RMR-CAP-L05-M04 - Interpret the Fictional R-26 Report (Supporting, step 4)", "primary_riasec": "C", "secondary_riasec": "I", "tertiary_riasec": "S", "riasec_reason": "Conventional work ensures records and methods meet review rules; Investigative work identifies unsupported claims; Social responsibility keeps public-facing recommendations careful.", "degree_gate": "Preferred", "direct_degree_mapping": "B.Sc. Chemistry; B.Sc. Environmental Science; B.Tech. Environmental Engineering; M.Sc. Environmental Science", "riasec_code_string": "CIS", "aptitude_profile": {"verbal_reasoning": 85, "logical_reasoning": 89, "numerical_reasoning": 79, "data_interpretation": 92, "pattern_recognition": 76, "spatial_reasoning": 61}, "big_five_profile": {"openness": 4, "conscientiousness": 5, "extraversion": 3, "agreeableness": 4, "emotional_stability": 5}, "work_values_profile": {"impact": 5, "status": 3, "autonomy": 3, "security": 5, "financial": 3, "lifestyle": 3, "creativity": 2, "leadership": 4}, "aptitude_assessment": {"areas": ["Data Interpretation", "Logical Reasoning", "Verbal Reasoning"], "rationale": "Water Safety Officer uses data interpretation, logical reasoning, verbal reasoning to keep both cup b observations and identify why a controlled retest is needed, check whether a filter advertisement is supported by the tests, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude."}, "big5_assessment": {"traits": ["Conscientiousness", "Emotional Stability", "Agreeableness"], "rationale": "Water Safety Officer benefits from conscientiousness, emotional stability, agreeableness when performing check whether a filter advertisement is supported by the tests and following through on r-26 safety-evidence gap report. Traits guide supportive coaching, not exclusion."}, "work_values_assessment": {"values": ["Impact", "Security", "Leadership"], "rationale": "This pathway may reward impact, security, leadership through the work of keep both cup b observations and identify why a controlled retest is needed and producing a clear retest and discrepancy register. These are possible work priorities, not salary or job guarantees."}}, "embedding_text": "ROLE\nName: Water Safety Officer\n\nCAREER CONTEXT\nIndustry: Water & Environmental Services\nDomain: Water Quality & Public Safety\nRole Family: Water Quality Compliance Officer\n\nROLE SUMMARY\nReviews test evidence and checks what remains unknown before an authorised water-safety decision. Future role: Water Quality Compliance Officer; students must not approve drinking-water safety.\n\nWORK CONTEXT\nA water-quality assurance team reviews sample evidence, conflicting results and test-method limitations before advising an authorised official. Approval is outside the student role.\n\nTYPICAL WORK ACTIVITIES\nKeep both Cup B observations and identify why a controlled retest is needed; Check whether a filter advertisement is supported by the tests; Mark the acid-base procedure as unverified when before/after evidence is absent; Review R-26 pH reports and missing microbial and chemical tests\n\nKEY RESPONSIBILITIES & ACTIONS\nInvestigate the Cup B Conflict: retain T1 and T2; record a clean-tool fresh-strip T3 separately; compare all three and flag the unexplained T2 conditions; Evaluate the Filter Advertisement: quote the claim, compare it with supported filtration results, identify missing controls and write a bounded decision; Review an Unverified Acid-Base Protocol: list the described steps, identify the missing starting and final evidence and classify the outcome as unverified; Interpret the Fictional R-26 Report: keep pH beside each sample ID; classify A near-neutral, B acidic and C basic; identify untested safety indicators\n\nDELIVERABLES & OUTPUTS\nRetest and discrepancy register; Claim-validation decision note; Unverified-protocol findings list; R-26 safety-evidence gap report; Learning modules: RMR-CAP-L02-M02 - Investigate the Cup B Conflict (Core, step 1), RMR-CAP-L04-M04 - Evaluate the Filter Advertisement (Important, step 2), RMR-CAP-L05-M03 - Review an Unverified Acid-Base Protocol (Important, step 3), RMR-CAP-L05-M04 - Interpret the Fictional R-26 Report (Supporting, step 4)\n\nINTEREST AND WORK-STYLE ALIGNMENT\nConventional work ensures records and methods meet review rules; Investigative work identifies unsupported claims; Social responsibility keeps public-facing recommendations careful.\n\nAPTITUDE ALIGNMENT\nKey areas: Data Interpretation, Logical Reasoning, Verbal Reasoning\nReadiness: Water Safety Officer uses data interpretation, logical reasoning, verbal reasoning to keep both cup b observations and identify why a controlled retest is needed, check whether a filter advertisement is supported by the tests, and interpret source-based records. These priorities are proposed role demands, not measured learner aptitude.\n\nBEHAVIOURAL ALIGNMENT\nKey traits: Conscientiousness, Emotional Stability, Agreeableness\nWork style: Water Safety Officer benefits from conscientiousness, emotional stability, agreeableness when performing check whether a filter advertisement is supported by the tests and following through on r-26 safety-evidence gap report. Traits guide supportive coaching, not exclusion.\n\nWORK-VALUE ALIGNMENT\nKey values: Impact, Security, Leadership\nMotivation: This pathway may reward impact, security, leadership through the work of keep both cup b observations and identify why a controlled retest is needed and producing a clear retest and discrepancy register. These are possible work priorities, not salary or job guarantees.\n\nEDUCATION AND ELIGIBILITY\nGate: Preferred\nStreams: B.Sc. Chemistry; B.Sc. Environmental Science; B.Tech. Environmental Engineering; M.Sc. Environmental Science\n"}'::jsonb;
 i uuid; d uuid; f uuid; roleid uuid; scopeid uuid; familyid uuid; contextid uuid; existing jsonb;
BEGIN

 i:=pg_temp.river_entity('industries',r->>'industry_code',r->>'industry_name','081cf05d-7a89-5c4a-897f-bde339d91318'::uuid);
 d:=pg_temp.river_entity('domains',r->>'domain_code',r->>'domain_name','c41d996c-bb21-5b7b-bbe9-893c56ee8437'::uuid);
 f:=pg_temp.river_entity('role_families',r->>'family_code',r->>'family_name','53d92d7d-963c-50fd-86b8-7e06428056d7'::uuid);
 roleid:=pg_temp.river_entity('role',r->>'role_code',r->>'role_name','1c03109d-ace8-5939-a09d-127fc099d8b3'::uuid);

 SELECT id INTO scopeid FROM public.industry_domains WHERE industry_id=i AND domain_id=d;
 IF scopeid IS NULL THEN
  INSERT INTO public.industry_domains(id,industry_id,domain_id) VALUES ('60f6de36-7629-56de-ab09-9e5c5a294c68',i,d) RETURNING id INTO scopeid;
 END IF;
 SELECT id INTO familyid FROM public.role_family_domains WHERE role_family_id=f AND industry_domain_id=scopeid;
 IF familyid IS NULL THEN
  INSERT INTO public.role_family_domains(id,role_family_id,industry_domain_id) VALUES ('f4947a85-6fef-5ff2-9497-020057fdd996',f,scopeid) RETURNING id INTO familyid;
 END IF;
 SELECT id INTO contextid FROM public.role_family_roles WHERE role_family_domain_id=familyid AND role_id=roleid;
 IF contextid IS NOT NULL THEN
  SELECT to_jsonb(x) INTO existing FROM public.role_family_roles x WHERE id=contextid;
  IF NOT existing @> (r->'profile') OR existing->>'is_active' IS DISTINCT FROM 'true' THEN
   RAISE EXCEPTION 'Existing role context differs from workbook or is inactive: %. Review before changing production.',r->>'role_name';
  END IF;
 ELSE

